package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/** Moves the claim to the status the change takes it to, refusing a change its status does not allow. */
public class ApplyClaimStatus {
    public void apply(@PathVariable("sheet") String sheet, @PathVariable("change") String change,
            @RequestParam("user") String user, @RequestBody ClaimStatusRequest body, @Val Claim claim,
            ClaimStatusChanger changer, Claims claims) throws InvalidClaimStatusChangeException {
        ClaimStatusChange requested = ClaimStatusChange.of(change);
        if (requested == null) {
            throw new InvalidClaimStatusChangeException("No such status change: " + change);
        }
        changer.change(sheet, user, claim, requested, body == null ? null : body.reason());
        if (requested == ClaimStatusChange.SETTLE) {
            // Settled one at a time: no longer part of a bulk settle batch.
            claims.setBatch(sheet, claim.id(), null);
        }
    }
}
package net.officefloor.hq.app.claim;

/**
 * Where a claim is in its life: only OPEN, PENDING and SETTLED claims count toward the totals. A clerk's settle of a
 * due above the clerk limit makes it PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). A steward
 * may void a SETTLED claim within 7 days of its settlement.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** The status a change takes this claim to, or null when the change is not allowed from here. */
    public ClaimStatus after(ClaimStatusChange change) {
        return switch (change) {
            case OPEN -> this == DRAFT ? OPEN : null;
            case SETTLE -> this == OPEN ? SETTLED : null;
            case PEND -> this == OPEN ? PENDING : null;
            case APPROVE -> this == PENDING ? SETTLED : null;
            case REJECT -> this == PENDING ? OPEN : null;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED ? VOID : null;
        };
    }
}
package net.officefloor.hq.app.claim;

/** A change of a claim's status, named by the last path segment, with the audit event it writes. */
public enum ClaimStatusChange {
    OPEN("CLAIM_OPENED"), SETTLE("CLAIM_SETTLED"), VOID("CLAIM_VOIDED"), APPROVE("CLAIM_APPROVED"),
    REJECT("CLAIM_REJECTED"),
    /** Not named in a path: a clerk's settle of a due above the clerk limit becomes this. */
    PEND("CLAIM_PENDING");

    private final String event;

    ClaimStatusChange(String event) {
        this.event = event;
    }

    public String event() {
        return event;
    }

    /** The change named in the path (open, settle, void, approve or reject), or null when there is no such change. */
    public static ClaimStatusChange of(String name) {
        for (ClaimStatusChange change : values()) {
            if (change != PEND && change.name().equalsIgnoreCase(name)) {
                return change;
            }
        }
        return null;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetArchive;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.hq.app.voidreason.VoidReasons;
import net.officefloor.hq.app.watch.Watches;
import org.springframework.stereotype.Service;

/** Moves a claim to the status a change takes it to, refusing a change its status does not allow; shared by a
 *  claim's own status buttons and the bulk actions. */
@Service
public class ClaimStatusChanger {

    /** How many days after its settlement a steward may still void a SETTLED claim. */
    public static final int VOID_SETTLED_DAYS = 7;

    private final Claims claims;
    private final People people;
    private final Rates rates;
    private final Periods periods;
    private final Roles roles;
    private final Settings settings;
    private final SheetClock clock;
    private final Audit audit;
    private final Rollup rollup;
    private final ClaimLog log;
    private final Watches watches;
    private final SheetArchive archive;
    private final VoidReasons voidReasons;

    public ClaimStatusChanger(Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log, Watches watches, SheetArchive archive,
            VoidReasons voidReasons) {
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.periods = periods;
        this.roles = roles;
        this.settings = settings;
        this.clock = clock;
        this.audit = audit;
        this.rollup = rollup;
        this.log = log;
        this.watches = watches;
        this.archive = archive;
        this.voidReasons = voidReasons;
    }

    /** Applies the change to the claim, writing nothing when it is refused. */
    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested)
            throws InvalidClaimStatusChangeException {
        change(sheet, user, claim, requested, null);
    }

    /** Applies the change to the claim (a reject gives its reason, a void the one chosen from the sheet's void reasons),
     *  writing nothing when it is refused. */
    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
            throws InvalidClaimStatusChangeException {
        requested = vet(sheet, user, claim, requested, reason);
        String voidReason = requested == ClaimStatusChange.VOID && voidReasons.any(sheet) ? reason.trim() : null;
        Person person = people.find(sheet, claim.person());
        Rollup.Snapshot before = rollup.take(sheet);
        ClaimStatus next = claim.status().after(requested);
        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
            throw new InvalidClaimStatusChangeException(
                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
        }
        // Opening gives the sheet's next number, or, while the sheet numbers by period from on or before its today,
        // the next number in the claim's period (X for none); a voided claim keeps the number it had (never reused).
        Claim changed = claim;
        if (requested == ClaimStatusChange.OPEN) {
            changed = number(sheet, claim);
            claims.setOpenedBy(sheet, claim.id(), user);
        }
        String fields = changed.statusAuditFields(person.name());
        // Settling (or approving a PENDING claim, its live figure then) fixes the due at the person's grade rate in force on the claim's date (or the figure its
        // statement bound), with its late charge frozen in; with no rate there is nothing to fix, so it stays live.
        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet)));
            claims.setSettledDue(sheet, claim.id(), due);
            fields += " due=" + (due == null ? "n/a" : due.toPlainString());
        }
        // Voiding a SETTLED claim reverses its frozen figure out of every total.
        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
            fields += " reversed=" + (claim.settledDue() == null ? "n/a" : claim.settledDue());
        }
        if (requested == ClaimStatusChange.REJECT) {
            fields += " reason=" + reason.trim();
        }
        if (voidReason != null) {
            voidReasons.voided(sheet, claim.id(), voidReason);
            fields += " reason=" + voidReason;
        }
        log.record(sheet, user, claim.id());
        audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + fields);
        // Settling or approving tells each user watching the person, before the rollup lines.
        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
            watches.notify(sheet, user, person.id(), person.name(), changed.shownNumber());
        }
        rollup.record(sheet, user, before);
    }

    /** Refuses the change the user may not make to the claim as it is now, writing nothing; otherwise gives the change
     *  it makes (a clerk's settle above the clerk limit is a move to PENDING). */
    public ClaimStatusChange vet(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
            throws InvalidClaimStatusChangeException {
        // A viewer changes nothing.
        if (Role.VIEWER.equals(roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("A viewer cannot change a claim");
        }
        if (archive.archived(sheet)) {
            throw new InvalidClaimStatusChangeException("An archived sheet cannot change");
        }
        // The permission matrix says which roles open, settle and void a claim.
        if ((requested == ClaimStatusChange.OPEN || requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.VOID)
                && !settings.permits(sheet, requested.name().toLowerCase(), roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Your role may not " + requested.name().toLowerCase() + " a claim");
        }
        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
            throw new InvalidClaimStatusChangeException("A claim due inside a closed period cannot change status");
        }
        // A steward voids a SETTLED claim only within 7 days of its settlement (its status log's last SETTLED date).
        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
            if (!Role.STEWARD.equals(roles.of(sheet, user))) {
                throw new InvalidClaimStatusChangeException("Only a steward voids a settled claim");
            }
            LocalDate settled = claim.settledOn();
            LocalDate today = clock.today(sheet);
            if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
                throw new InvalidClaimStatusChangeException(
                        "A settled claim may be voided only within " + VOID_SETTLED_DAYS + " days of its settlement");
            }
        }
        if (requested == ClaimStatusChange.SETTLE && claim.deferred()) {
            throw new InvalidClaimStatusChangeException("A deferred claim cannot be settled until its date");
        }
        // Four eyes: the user who opened a claim may not settle it, nor approve it.
        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
                && user.equals(claim.openedBy())) {
            throw new InvalidClaimStatusChangeException("The user who opened a claim cannot settle or approve it");
        }
        // Nor may the user who last edited it.
        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
                && user.equals(claims.editedBy(sheet, claim.id()))) {
            throw new InvalidClaimStatusChangeException("The user who last edited a claim cannot settle or approve it");
        }
        // Only a steward approves or rejects a PENDING claim; a reject gives a reason.
        if ((requested == ClaimStatusChange.APPROVE || requested == ClaimStatusChange.REJECT)
                && !Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Only a steward approves or rejects a claim");
        }
        if (requested == ClaimStatusChange.REJECT && (reason == null || reason.isBlank())) {
            throw new InvalidClaimStatusChangeException("A reject needs a reason");
        }
        // While the sheet has void reasons, a void needs one chosen from them (with none, a void takes no reason).
        if (requested == ClaimStatusChange.VOID && voidReasons.any(sheet)) {
            String voidReason = reason == null ? "" : reason.trim();
            if (voidReason.isEmpty() || !voidReasons.has(sheet, voidReason)) {
                throw new InvalidClaimStatusChangeException("A void needs a reason from the sheet's void reasons");
            }
        }
        Person person = people.find(sheet, claim.person());
        // A claim whose due is above the proof threshold in force on its date (its person's grade's then when it has
        // one, else the sheet's) is settled or approved only once it has
        // a proof (a due of n/a is above no threshold); checked before the clerk limit, so it never goes to PENDING.
        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
            BigDecimal threshold = settings.proofThreshold(sheet, person.gradeOn(claim.date()),
                    LocalDate.parse(claim.date()));
            if (threshold != null && claim.proofs() == 0) {
                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                        settings.late(sheet, clock.today(sheet)));
                if (due != null && due.compareTo(threshold) > 0) {
                    throw new InvalidClaimStatusChangeException(
                            "A claim whose due is above the proof threshold needs a proof before it is settled or approved");
                }
            }
        }
        // A claim whose due is above the note threshold in force on its date is opened only with a note (a due of n/a
        // is above no threshold).
        if (requested == ClaimStatusChange.OPEN && (claim.note() == null || claim.note().isBlank())) {
            BigDecimal threshold = settings.noteThreshold(sheet, LocalDate.parse(claim.date()));
            if (threshold != null) {
                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                        settings.late(sheet, clock.today(sheet)));
                if (due != null && due.compareTo(threshold) > 0) {
                    throw new InvalidClaimStatusChangeException(
                            "A claim whose due is above the note threshold needs a note before it is opened");
                }
            }
        }
        // A clerk settles only a due at or below the sheet's clerk limit (a due of n/a is within any limit); above
        // it the claim goes to PENDING for a steward to approve. A steward settles anything.
        if (requested == ClaimStatusChange.SETTLE && claim.status() == ClaimStatus.OPEN
                && Role.CLERK.equals(roles.of(sheet, user))) {
            BigDecimal limit = settings.clerkLimit(sheet);
            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet)));
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                requested = ClaimStatusChange.PEND;
            }
        }
        if (claim.status().after(requested) == null) {
            throw new InvalidClaimStatusChangeException(
                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
        }
        return requested;
    }

    /**
     * Gives an opening claim the sheet's next number, or, while the sheet numbers by period from on or before its
     * today, the next number in the claim's period (X for none); returns the claim so numbered.
     */
    public Claim number(String sheet, Claim claim) {
        LocalDate from = settings.periodNumberingFrom(sheet);
        if (from != null && !clock.today(sheet).isBefore(from)) {
            String period = periods.nameOn(sheet, LocalDate.parse(claim.dueBy()));
            String key = period == null ? "" : period;
            Claim numbered = claim.withPeriodNumber((period == null ? "X" : period) + "-" + claims.nextPeriodNumber(sheet, key));
            claims.setPeriodNumber(sheet, claim.id(), numbered.periodNumber());
            return numbered;
        }
        Claim numbered = claim.withNumber(claims.nextNumber(sheet));
        claims.setNumber(sheet, claim.id(), numbered.number());
        return numbered;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/** Writes a line to a claim's status log as it is added and each time its status changes. */
@Service
public class ClaimLog {

    private final JdbcTemplate jdbc;
    private final Claims claims;
    private final People people;
    private final Rates rates;
    private final Settings settings;
    private final SheetClock clock;

    public ClaimLog(JdbcTemplate jdbc, Claims claims, People people, Rates rates, Settings settings, SheetClock clock) {
        this.jdbc = jdbc;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.clock = clock;
    }

    /** Logs the claim's status as the store now holds it, by the user on the sheet's today, with its due then. */
    public void record(String sheet, String user, long id) {
        Claim claim = claims.find(sheet, id);
        Person person = people.find(sheet, claim.person());
        LocalDate today = clock.today(sheet);
        BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                settings.late(sheet, today));
        jdbc.update("INSERT INTO claim_log (sheet, claim, status, by_user, on_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                sheet, id, claim.status().name(), user, Date.valueOf(today), due == null ? "n/a" : due.toPlainString());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.Dated;

/**
 * A claim as the screen shows it: amount with two decimals, date (ISO yyyy-MM-dd), note, status and its number on
 * the sheet (given when opened and kept once voided; null while a draft), and its due fixed when settled (two decimals;
 * null until settled, and when the grade had no rate then), and the user who opened it (null until opened), and
 * whether its person's last statement bound it, with the figure it bound (null when the grade had no rate then), and
 * the number of the claim it corrects (null unless it is a correction), and the date it rounds on: its own, or for
 * a correction the date of the claim it corrects, and its number within its period (<period>-<n>, or X-<n> in no
 * period) when it was opened while the sheet numbered by period, in place of a number on the sheet (null otherwise),
 * and its due-by (yyyy-MM-dd), fixed when it was added from the terms of its person's grade in force on its date,
 * and its status log, oldest first, and the date it was last deferred until (null when never), with whether it is
 * deferred now: OPEN (or VOID, voided while deferred) with that date after the sheet's today, and its proofs count, and the number (as it shows) of
 * the claim it was split off (null unless it was), and the user whose open editor locks it (null when none does),
 * and whether it was added while its period was soft-closed (a late entry), and the sheet's today it was last
 * reminded on (null when never), and its external reference (null for none), and its tags (lower-cased, sorted),
 * with every tag it has ever carried, and its comments, in the order written, and the number of the bulk settle
 * batch that last settled it (null when settled one at a time, or never).
 */
public record Claim(long id, long person, String amount, String date, String note, ClaimStatus status,
        Integer number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
        String roundsOn, String periodNumber, String dueBy, List<ClaimLogLine> log, String deferredUntil, boolean deferred, int proofs,
        String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref, List<String> tags,
        List<String> tagsEver, List<ClaimComment> comments, Integer batch) {

    /** Whether this claim is a correction: a negative amount, naming the number (as it shows) of the settled claim it corrects. */
    public boolean correction() {
        return amount.startsWith("-");
    }

    /** The audit fields of this claim for the named person, as {@link ClaimInput#auditFields}. */
    public String auditFields(String person) {
        return "person=" + person + " amount=" + amount + " date=" + date;
    }

    /** This claim, numbered: its audit fields end with number=<number> when it has one. */
    public Claim withNumber(Integer number) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch);
    }

    /** This claim, numbered within its period: its audit fields end with number=<period number>. */
    public Claim withPeriodNumber(String periodNumber) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch);
    }

    /** This claim with another date (yyyy-MM-dd), as once re-dated. */
    public Claim withDate(String date) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch);
    }

    /** This claim with another amount (two decimals), as its remaining amount once split. */
    public Claim withAmount(String amount) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch);
    }

    /** This claim, settled with its due fixed (null when its grade had no rate). */
    public Claim withSettledDue(String settledDue) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch);
    }

    /** This claim as an OPEN claim bound by no statement and with no due fixed: the figure it would have live. */
    public Claim asOpenUnbound() {
        return new Claim(id, person, amount, date, note, ClaimStatus.OPEN, number, null, openedBy, false, null, corrects, roundsOn, periodNumber, dueBy, log, deferredUntil, deferred, proofs, splitFrom, lockedBy, lateEntry, remindedOn, ref, tags, tagsEver, comments, batch);
    }

    /** This claim as it stands with the date for the sheet's today: deferred while OPEN (or VOID) with its deferred-until after it. */
    public Claim on(LocalDate today) {
